};

#define CXL_INVALID_DIRTY_SHUTDOWN_COUNT ULLONG_MAX
static umode_t cxl_dimm_visible(struct kobject *kobj,
				struct attribute *a, int n)
{
	if (a == &dev_attr_dirty_shutdown.attr) {
